RULES = json.loads("{\"source\":\"Stranger Builds event_book via connected plugin\",\"source_url\":\"https://strangerbuilds.com/rules\",\"fetched_at\":\"2026-11-07 15:56:07 UTC\",\"book_version\":\"2026-11-06.c70459756f\",\"challenge\":{\"id\":\"fetch-ai\",\"app_id\":\"fetch_ai\",\"sponsor\":\"Fetch.ai\",\"track\":\"Real users\",\"title\":\"Get your agent hired\",\"status\":\"confirmed\",\"rule\":\"New repo only: created after the opening, Fri 30 Oct 23:00 UTC.\",\"ask\":{\"channel\":\"#fetchai\",\"who\":\"Fetch.ai's team\"},\"tagline\":null,\"tech\":\"Fetch.ai puts your AI agent on a marketplace where people find it and hire it by chat.\",\"approval\":null,\"brief\":[\"For builders who like agents more than apps: an agent that does one real job, that people, or other agents, hire.\",\"Ship it: on Agentverse, speaking the Chat Protocol, findable by anyone in ASI:One.\",\"Feedback: 1 builder outside your team hires it and leaves feedback (what worked, would they use it again). Improve it: change one thing because of their feedback.\",\"Proof: the agent on Agentverse, 1 hire, its feedback. Agents hiring agents, or getting paid, score higher.\"],\"short\":{\"build\":\"An agent that does one real job people, or other agents, hire.\",\"done\":\"It's on Agentverse and findable in ASI:One, 1 builder hired it and left feedback, and you changed one thing because of their feedback.\"},\"proof\":\"the agent on Agentverse, 1 hire, its feedback. Agents hiring agents, or getting paid, score higher.\",\"judging\":null,\"credits\":null,\"definitions\":{\"hire\":\"A hire is a Trick or Feedback try made through ASI:One by someone from another team, who leaves feedback. The app counts them.\"},\"game\":{\"for_who\":\"You like agents more than apps. No frontend: the chat is the product. A little Python gets you there.\",\"ideas\":[\"Check a lease for red flags\",\"Rebook a cancelled flight\",\"Chase unpaid invoices\"],\"need\":[\"Agentverse and ASI:One\",\"A new GitHub repo, created after the opening (Fri 30 Oct, 23:00 UTC)\"],\"perk\":\"Start right now with the Duck on ASI:One\",\"why\":\"Most agents never leave the laptop they were built on. The skill now is an agent other people actually put to work.\",\"judges\":[\"Is it really useful\",\"How it uses Fetch.ai (agents hiring agents, or getting paid, earn extra)\",\"It works every time\",\"What builders said in their feedback\",\"Real use outside the event\"],\"tools\":[{\"id\":\"asi\",\"label\":\"1. Talk to the Duck on ASI:One\",\"sub\":\"Start right now with the Duck on ASI:One\",\"action\":\"Talk to the Duck\",\"link\":\"https://asi1.ai\"},{\"id\":\"agentverse\",\"label\":\"2. Create your Agentverse account\",\"sub\":\"Where your agent lives and speaks the Chat Protocol\",\"action\":\"Open Agentverse\",\"link\":\"https://agentverse.ai\"},{\"id\":\"guide\",\"label\":\"3. Create your agent\",\"sub\":\"A uAgent with the Chat Protocol: Fetch.ai Innovation Lab's guide\",\"action\":\"Read it\",\"link\":\"https://innovationlab.fetch.ai/resources/docs/agent-creation/uagent-creation\"},{\"id\":\"repo\",\"label\":\"4. Create a new GitHub repo\",\"sub\":\"Created after the opening, Fri 30 Oct 23:00 UTC\",\"action\":\"New repo\",\"link\":\"https://github.com/new\"}],\"clause\":\"By Sunday 8 Nov, 1 builder outside your team hires your agent, and you change one thing because of their feedback.\",\"aim_hint\":\"Users is the dare. Shipped is honest. Working is easy mode.\",\"specific\":\"Be specific. Nobody hires a vague agent.\",\"example\":{\"what\":\"An agent that checks a lease for red flags before you sign\",\"who\":\"People renting their first flat\"}},\"steps\":[{\"id\":\"pick-idea\",\"order\":1,\"title\":\"Pick an idea\",\"do\":\"An agent that does one real job, that people, or other agents, hire.\",\"done_when\":\"You named the job and who hires it.\",\"status\":\"confirmed\",\"resources\":[],\"cta\":{\"label\":\"Name your agent's job\"},\"optional\":false,\"evidence\":[{\"key\":\"job\",\"label\":\"The job\",\"ask\":\"The one real job your agent does.\",\"kind\":\"text\",\"required\":true,\"checked_by\":\"self\",\"app\":\"commitment.promise\"},{\"key\":\"who_hires\",\"label\":\"Who hires it\",\"ask\":\"Who hires it: people, other agents, or both.\",\"kind\":\"text\",\"required\":true,\"checked_by\":\"self\",\"app\":\"commitment.for_whom\"}]},{\"id\":\"ship-it\",\"order\":2,\"title\":\"Ship it\",\"do\":\"On Agentverse, speaking the Chat Protocol, findable by anyone in ASI:One.\",\"done_when\":\"The agent is on Agentverse and anyone can find it in ASI:One.\",\"status\":\"confirmed\",\"resources\":[{\"label\":\"Agentverse\",\"url\":\"https://agentverse.ai\"},{\"label\":\"Guide: Create a uAgent\",\"url\":\"https://innovationlab.fetch.ai/resources/docs/agent-creation/uagent-creation\"},{\"label\":\"A new GitHub repo\",\"url\":\"https://github.com/new\"},{\"label\":\"ASI:One\",\"url\":\"https://asi1.ai\"}],\"cta\":{\"label\":\"Add your Agentverse link\"},\"optional\":false,\"evidence\":[{\"key\":\"agent_address\",\"label\":\"Your agent on Agentverse\",\"ask\":\"The link to your agent on Agentverse (its public profile). Any link that shows your agent counts.\",\"kind\":\"link\",\"required\":true,\"checked_by\":\"system\",\"app\":\"proof.agentverse_address\",\"day_prize\":true,\"sponsor_proof\":true},{\"key\":\"asi_link\",\"label\":\"Find it in ASI:One\",\"ask\":\"The link where anyone finds your agent in ASI:One.\",\"kind\":\"link\",\"required\":true,\"checked_by\":\"system\",\"app\":\"project.public_url\"},{\"key\":\"repo_link\",\"label\":\"Your agent's public repo\",\"ask\":\"The agent's public repo, created after the opening (Fri 30 Oct, 23:00 UTC), not a fork.\",\"kind\":\"link\",\"required\":true,\"checked_by\":\"system\",\"app\":\"project.repo_url\"}]},{\"id\":\"get-feedback\",\"order\":3,\"title\":\"Get feedback\",\"do\":\"1 builder from another team hires it through ASI:One in Trick or Feedback and leaves feedback (what worked, would they use it again). A hire is a Trick or Feedback try made through ASI:One by someone from another team. The app counts them.\",\"done_when\":\"1 hire counted by the app: a Trick or Feedback try through ASI:One, by someone from another team, with feedback.\",\"status\":\"confirmed\",\"resources\":[],\"cta\":{\"label\":\"Get hired once\"},\"optional\":false,\"evidence\":[{\"key\":\"hires\",\"label\":\"Hires with feedback\",\"ask\":\"1 builder outside your team hires it and leaves feedback: what worked, would they use it again.\",\"kind\":\"count\",\"required\":true,\"checked_by\":\"system\",\"min\":1,\"counts\":\"Trick or Feedback tries made through ASI:One by people from other teams, each with feedback\",\"app\":\"tries.notes\"}]},{\"id\":\"improve-it\",\"order\":4,\"title\":\"Improve it\",\"do\":\"Change one thing because of their feedback.\",\"done_when\":\"One thing changed because of their feedback.\",\"status\":\"confirmed\",\"resources\":[],\"cta\":{\"label\":\"Note what you changed\"},\"optional\":false,\"evidence\":[{\"key\":\"change\",\"label\":\"What you changed\",\"ask\":\"One thing you changed because of their feedback: what they said and what you changed.\",\"kind\":\"text\",\"required\":true,\"checked_by\":\"judges\",\"app\":\"record_change\"}]},{\"id\":\"submit\",\"order\":5,\"title\":\"Submit\",\"do\":\"Submit by Sunday 8.\",\"done_when\":\"Submit by Sunday 8.\",\"status\":\"confirmed\",\"resources\":[],\"cta\":{\"label\":\"Submit\"},\"optional\":false,\"evidence\":[{\"key\":\"launch_link\",\"label\":\"Demo link\",\"ask\":\"It can be: a link to an X post, a demo video, or a link to your app in DEMO MODE.\",\"kind\":\"link\",\"required\":false,\"checked_by\":\"judges\",\"app\":\"submission.launch_proof\"},{\"key\":\"test_access\",\"label\":\"Test access for judges\",\"ask\":\"Only if judges need a login to try it. Only judges see this.\",\"kind\":\"text\",\"required\":false,\"checked_by\":\"judges\",\"private\":true,\"app\":\"submission.test_access\"}]}]},\"general_rules\":[{\"section\":\"rules\",\"title\":\"Accepting the Terms\",\"text\":\"Builders accept the Terms, the Official Rules and the Privacy Notice by ticking 'I accept the terms and conditions' when signing the pact. Terms win on legal matters, the Rules on how the competition works.\",\"when\":null,\"when_text\":null,\"city\":null},{\"section\":\"rules\",\"title\":\"Best of the day (each in-person city)\",\"text\":\"Each in-person city has a Best of the day: projects started after the opening (Fri 30 Oct, 23:00 UTC), with at least one team member at the venue, submitted in the app before the venue's judges look at the projects (each venue's schedule). The judges see one ranking in the app (never the builders), 5 finalists pitch, and the jury decides and announces the winners there at 17:30. Each city has one total for its best projects; the jury decides how many winners and how it is divided.\",\"when\":\"2026-10-31\",\"when_text\":\"Sat 31 Oct, 17:30 local\",\"city\":null},{\"section\":\"rules\",\"title\":\"Who picks which prize\",\"text\":\"Best of the day: that venue's jury, announced there the same day. Challenge prizes: judges shortlist, NERDCONF picks (each shortlisted project gets at least 2 reviews). People's Choice: most votes. Community Cup: the community whose members created the most projects. Copilot Max: drawn at random on 19 Nov.\",\"when\":null,\"when_text\":null,\"city\":null},{\"section\":\"rules\",\"title\":\"GitHub Copilot Max subscription\",\"text\":\"One builder wins a one-year GitHub Copilot Max subscription, drawn at random on 19 November among the members of the projects that win a prize. It goes to a person, not a project.\",\"when\":\"2026-11-19\",\"when_text\":\"Thu 19 Nov\",\"city\":null},{\"section\":\"rules\",\"title\":\"'Never by chance' vs the Copilot draw\",\"text\":\"Settled in the live copy (30 Oct): the Rules say the Copilot Max draw \\\"is the only prize decided by chance\\\", and the Terms v1.6 no longer say \\\"never by chance\\\".\",\"when\":null,\"when_text\":null,\"city\":null},{\"section\":\"rules\",\"title\":\"How prizes are paid\",\"text\":\"Winners are provisional until verified: within 10 days of NERDCONF's email the recipient sends identity, a W-9 or W-8BEN and a payment account. Prizes are paid by NERDCONF LLC within 30 days of the announcement; values are gross and tax may be withheld. Only winners announced through official channels are valid.\",\"when\":null,\"when_text\":null,\"city\":null},{\"section\":\"rules\",\"title\":\"New work counts from the switch\",\"text\":\"Only work started after the opening counts: Fri 30 Oct, 23:00 UTC (Saturday 10:00 in Melbourne).\",\"when\":\"2026-10-30T23:00Z\",\"when_text\":\"From Fri 30 Oct, 23:00 UTC\",\"city\":null},{\"section\":\"rules\",\"title\":\"What you submit is new\",\"text\":\"Bring your users, not your product: what you submit is built this week, started after the opening, Fri 30 Oct 23:00 UTC, with its own link. Your audience, tools, AI and open-source libraries come with you. After the deadline, a review checks that each project is new (the repo's creation date and history, or the Base44 app) and flags anything built before.\",\"when\":null,\"when_text\":null,\"city\":null},{\"section\":\"rules\",\"title\":\"Prizes in public: USD 10K in prizes and credits\",\"text\":\"USD 10K in prizes and credits.\",\"when\":null,\"when_text\":null,\"city\":null},{\"section\":\"rules\",\"title\":\"Sponsor tech needed for a money prize\",\"text\":\"To win a money prize a project must really use at least one sponsor's technology, with proof. An account or a logo doesn't count.\",\"when\":null,\"when_text\":null,\"city\":null},{\"section\":\"rules\",\"title\":\"How projects are judged\",\"text\":\"How projects are judged (rules, section 12, strangerbuilds.com/rules): \\\"People pick the winners. The system only helps them look.\\\" What judges look at, the four criteria, equal weight, each scored 1 to 5: 1) Do I remember it? Is it different? (would you tell a friend about it tomorrow). 2) Does it work? (you could use it yourself, now, without the team explaining). 3) Is the sponsor integration real? (the sponsor's tech does real work, not a logo or an empty account). 4) Does it show what they learned? (from the demo and the commitment: what changed in how they build). Best of the day (San Francisco, Melbourne, Bangalore, Saturday 31 October): a project competes if it submits in the app before its city's cut, 16:10 local time, with a sponsor proof declared and not rejected and at least one team member at that venue. At the cut the app takes a snapshot of that venue's submitted projects; the judges look at them and see the same live ranking. The top 5 finalists pitch (2 minutes each), each judge scores each finalist from 1 to 10, and the highest average wins; the jury announces the winners there the same day (17:30 local in San Francisco and Melbourne). Challenge prizes and the final round: judged online after the close (judges vote 10 to 15 November), among the projects that completed. For each challenge the judges shortlist the top projects (at least 2 judge reviews each) and NERDCONF picks the winners from the shortlist. The system suggests where to look first (extra points for real users and for changes made from feedback); it uses no score formula. Real use outside the event (the people's vote, usage you can show) is part of what judges see. Results Thursday 19 November. Fair judging: judges disclose conflicts and step aside; sponsors can't pick a winner outside this process; judges look only at what you submitted; ties are decided by NERDCONF after hearing the judges; decisions are final; winners are provisional until the proof checks pass, and if one fails the next eligible project wins.\",\"when\":null,\"when_text\":\"Sat 31 Oct (day prize) and 10 to 15 Nov (online)\",\"city\":null},{\"section\":\"rules\",\"title\":\"Who runs it, and governing law\",\"text\":\"NERDCONF LLC (Wyoming) organises Stranger Builds and pays the prizes; MLAI is community partner in Melbourne; sponsors, venues and partners are not organisers. Contact: hey@nerdconf.com. Argentine law, courts of Buenos Aires, after 30 days of good-faith discussion.\",\"when\":null,\"when_text\":null,\"city\":null},{\"section\":\"rules\",\"title\":\"Who can take part\",\"text\":\"18 or older; not in a sanctioned place; one account per person. NERDCONF crew and judges may build but not win; judges never in what they judge; sponsor staff cannot win their own sponsor's challenge.\",\"when\":null,\"when_text\":null,\"city\":null},{\"section\":\"rules\",\"title\":\"Teams of 1 or 2\",\"text\":\"Teams are 1 or 2 people; solo is judged the same. Nobody tries their own team's project.\",\"when\":null,\"when_text\":null,\"city\":null},{\"section\":\"rules\",\"title\":\"Your project is yours and public; sponsor contact is opt-in\",\"text\":\"Teams own their project. Its page is public from creation and joins the gallery and the Duck World once it ships (Ship it); NERDCONF gets a licence to show it; take-down on request within 7 days. Never public: email and the level picked at registration. Sponsors get a builder's name, email, role and company only if they switched on 'Share my details with sponsors' (off by default). Communities see only counts for their clan.\",\"when\":null,\"when_text\":null,\"city\":null},{\"section\":\"rules\",\"title\":\"Credits and keys are not prizes\",\"text\":\"Base44 credits and TrueFoundry AI Gateway keys are for building your event project: personal or per team, limited, may expire. They are not prizes.\",\"when\":null,\"when_text\":null,\"city\":null},{\"section\":\"rules\",\"title\":\"Taking money from users\",\"text\":\"Money is a bonus, never a requirement. The only supported payment route inside projects is Base44's built-in Stripe; payments between builders and their users are theirs, NERDCONF doesn't process or refund them. Label test payments as tests.\",\"when\":null,\"when_text\":null,\"city\":null},{\"section\":\"rules\",\"title\":\"Conduct, fair play and photos\",\"text\":\"No plagiarism, faked tries, notes or votes, more than one account, or buying votes; no harassment, malware or exposing keys or data. The code of conduct applies online and in person; reports to hey@nerdconf.com or any crew member; a person reviews flags and the builder gets one answer before any decision. In-person days are photographed and filmed: tell the crew at check-in or email hey@nerdconf.com to not be featured.\",\"when\":null,\"when_text\":null,\"city\":null},{\"section\":\"rules\",\"title\":\"Up to 2 projects at a time per person\",\"text\":\"Each person can be in up to 2 projects at a time. Teams are 1 or 2 people.\",\"when\":null,\"when_text\":null,\"city\":null},{\"section\":\"rules\",\"title\":\"Where the rules live\",\"text\":\"The Official Rules: strangerbuilds.com/rules (updated 30 Oct). The Terms and Conditions: strangerbuilds.com/terms (the version live on the page wins). The code of conduct: strangerbuilds.com/conduct. If a copy differs from these pages, the pages win.\",\"when\":null,\"when_text\":null,\"city\":null}]}")
